mapper.select:
SELECT capability_id,endpoint,auth_kind,api_key_header,credential_id,credential_revision,revision
  FROM pf.mcp_connector_configuration WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId}
  AND capability_id>#{after} ORDER BY capability_id LIMIT #{limit}

mapper.update:
UPDATE pf.mcp_connector_configuration SET endpoint=#{config.endpoint},auth_kind=#{config.authKind},api_key_header=#{config.apiKeyHeader,jdbcType=VARCHAR},
  credential_id=#{config.credentialId,jdbcType=OTHER},credential_revision=#{config.credentialRevision,jdbcType=BIGINT},revision=revision+1,updated_at=clock_timestamp()
  WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId} AND capability_id=#{config.id} AND revision=#{expected}
